B.NO=new A.cL("Shipwright",B.Wy)
B.Vr=s(["The player stirs, violently coughing up seawater. There is a distinct taste of iron admist the saltiness. The chill on your flesh is contrasted by the burning in your side."],t.s)
B.Nw=new A.cp("Next","intro_show_stranger",!0,!1)
B.Y8=s([B.Nw],t.u)
B.Oe=new A.cf(B.ae,B.Vr,null,null,null,B.Y8)
B.Vi=s([B.Oe],t.J)
B.NP=new A.cL("Narrator",B.Vi)
B.VT=s(["I...I...I don't know... I..."],t.s)
B.Nr=new A.cp("Try to Remember","intro_show_british_officer",!0,!1)
B.Yg=s([B.Nr],t.u)
B.Oh=new A.cf(B.ae,B.VT,null,null,null,B.Yg)
B.UG=s([B.Oh],t.J)
B.NQ=new A.cL("Player",B.UG)
B.XC=s(["I... I cannot remember."],t.s)
B.Ns=new A.cp("Continue","intro_ask_player_name",!0,!1)
