B.Yd=s([B.Ov],t.J)
B.O3=new A.cL("Narrator",B.Yd)
B.Ub=s(["Lightning tears across the water as the Kraken returns, charged with violent energy.","This encounter will become the Kraken's second phase."],t.s)
B.Nn=new A.cp("Face the Electro Kraken","start_electro_kraken_fight",!0,!1)
